INSERT INTO `roles` VALUES (1,'SYSTEM_ADMIN','System Administrator',NULL,'Full technical administration. Not a statutory office.',1,1,1,'2026-08-19 05:50:52','2026-08-19 05:50:52'),(2,'CHAIRMAN','Chairman, ETPB',NULL,'Extends the 60-day assessment period, calls for record, remits rent under Clause 12, and cancels a tenancy obtained by fraud under Clause 23.',10,1,1,'2026-08-19 05:50:52','2026-08-19 05:50:52'),(3,'ADMINISTRATOR','Administrator',NULL,'Approves regularization within one month after recording reasons (Clause 3(ii)(d)); may call for the record of any assessment.',20,1,1,'2026-08-19 05:50:52','2026-08-19 05:50:52'),(4,'DISTRICT_OFFICER','District Officer',NULL,'Deputy or Assistant Administrator in charge of a district office (Clause 2(i)(f)). Assesses and fixes rent, issues notices, hears objections and executes the tenancy agreement.',40,1,1,'2026-08-19 05:50:52','2026-08-19 05:50:52'),(5,'DEALING_ASSISTANT','Dealing Assistant',NULL,'Data entry for walk-in applicants, diary and dispatch of notices.',60,1,1,'2026-08-19 05:50:52','2026-08-19 05:50:52'),(6,'ACCOUNTS_OFFICER','Accounts Officer / Cashier',NULL,'Verifies the fee instrument with the bank and posts receipts against the arrears ledger. Cannot fix rent — separation of duties.',55,1,1,'2026-08-19 05:50:53','2026-08-19 05:50:53'),(7,'LEGAL_OFFICER','Legal Officer',NULL,'Maintains the litigation register, restraining orders and direction cases; flags properties as sub judice.',55,1,1,'2026-08-19 05:50:53','2026-08-19 05:50:53'),(8,'AUDITOR','Auditor (read-only)',NULL,'Read-only access to everything, including the audit log. No mutations.',90,1,1,'2026-08-19 05:50:53','2026-08-19 05:50:53'),(9,'APPLICANT','Applicant / Occupant',NULL,'An existing occupant applying to have possession regularized under Clause 3(ii).',100,1,1,'2026-08-19 05:50:53','2026-08-19 05:50:53');
/*!40000 ALTER TABLE `roles` ENABLE KEYS */;
