INSERT INTO `settings` VALUES (1,'possession_cutoff_date','2009-12-31','DATE','eligibility','Possession cut-off date','Possession must be prior to 01-01-2010.','Scheme 1977, Clause 3(ii)(a)','1977-01-01',NULL,0,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(2,'arrears_base_date','2000-07-01','DATE','arrears','Arrears statutory base date','Arrears run from 01-07-2000, the date of occupation, or the date of judicial verdict - whichever is earlier.','Scheme 1977, Clause 3(ii)(b)','1977-01-01',NULL,0,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(3,'assessment_base_date','2006-07-01','DATE','assessment','Assessment base date','Assessment / re-assessment is made with effect from 01-07-2006.','Scheme 1977, Clause 10(i)','1977-01-01',NULL,0,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(4,'enhancement_rate','8.00','DECIMAL','assessment','Annual rent enhancement rate (%)','Enhancement in rent at eight per cent per annum.','Scheme 1977, Clause 11(ii)','1977-01-01',NULL,0,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(5,'enhancement_method','COMPOUND','STRING','assessment','Enhancement method','SIMPLE or COMPOUND. The Scheme does not specify; over 24 years compound yields about 6.34x the base against about 2.92x simple. PENDING A WRITTEN ETPB RULING.','Scheme 1977, Clause 11(ii)','1977-01-01',NULL,1,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(6,'reassessment_cycle_years','6','INT','assessment','Periodical re-assessment cycle (years)','Re-assessment after every six years.','Scheme 1977, Clause 11(i)','1977-01-01',NULL,0,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(7,'objection_window_days','15','INT','due_process','Objection window (days)','Fifteen days from receipt of notice to file objections.','Scheme 1977, Clause 10(i)(c)','1977-01-01',NULL,0,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(8,'assessment_sla_days','60','INT','due_process','Assessment completion SLA (days)','The entire process is completed within 60 days of the first notice, extendable by the Chairman on merit.','Scheme 1977, Clause 10(i)(e)','1977-01-01',NULL,0,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(9,'admin_approval_sla_days','30','INT','approval','Administrator approval SLA (days)','Regularization is approved by the Administrator within one month after recording reasons.','Scheme 1977, Clause 3(ii)(d)','1977-01-01',NULL,0,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(10,'processing_fee','5000.00','DECIMAL','fee','Application processing fee (Rs.)','Payable by pay order, banker cheque or demand draft in favour of Chairman ETPB.','Board requirement (not in the 1977 Scheme text)','1977-01-01',NULL,1,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(11,'max_instalments','24','INT','arrears','Maximum arrears instalments','Reasonable monthly instalments, not exceeding 24 in number.','Scheme 1977, Clause 13','1977-01-01',NULL,0,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(12,'do_penalty_ceiling','100000.00','DECIMAL','enforcement','District Officer penalty ceiling (Rs.)','Penalty to the extent of Rs. 100,000 for a rectifiable breach.','Scheme 1977, Clause 22','1977-01-01',NULL,0,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(13,'ejectment_show_cause_days','7','INT','enforcement','Ejectment show-cause period (days)','A period of not less than seven days to show cause.','Scheme 1977, Clause 21(a)','1977-01-01',NULL,0,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(14,'ejectment_vacation_days','60','INT','enforcement','Maximum vacation period (days)','Not more than sixty days for vacation of the premises.','Scheme 1977, Clause 21(c)','1977-01-01',NULL,0,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(15,'milestone_years','2000,2004,2008,2012,2016,2020,2024','STRING','reporting','Rent table milestone years','Presentation grid for the rent assessment table. This is a view over the year-by-year ledger; the 6-year statutory cycle still governs the law.','Requirements specification','1977-01-01',NULL,1,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(16,'default_unit_profile','REVENUE','STRING','measurement','Default area conversion profile','REVENUE (1 Marla = 272.25 sqft) or URBAN (1 Marla = 225 sqft).','Pakistani revenue measurement practice','1977-01-01',NULL,1,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(17,'organisation_name','Evacuee Trust Property Board','STRING','general','Organisation name','Printed on notices, orders and reports.',NULL,'1977-01-01',NULL,1,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL),(18,'scheme_name','Regularization of Possession','STRING','general','Scheme name','Project / scheme title.',NULL,'1977-01-01',NULL,1,NULL,NULL,'2026-08-19 05:50:51','2026-08-19 05:50:51',NULL);
/*!40000 ALTER TABLE `settings` ENABLE KEYS */;
UNLOCK TABLES;

