image/png,image/tiff',10240,11,1,'2026-08-19 05:50:51','2026-08-19 05:50:51'),(12,'AFFIDAVIT_POSSESSION','Affidavit (date of possession and nominee)','حلف نامہ','AFFIDAVIT',NULL,1,1,0,1,'application/pdf,image/jpeg,image/png,image/tiff',10240,12,1,'2026-08-19 05:50:51','2026-08-19 05:50:51'),(13,'CNIC_COPY','CNIC Copy','شناختی کارڈ کی نقل','IDENTITY',NULL,0,1,0,0,'application/pdf,image/jpeg,image/png,image/tiff',10240,13,1,'2026-08-19 05:50:51','2026-08-19 05:50:51'),(14,'NOMINATION_FORM','Nomination Form (Scheme para 3)','نامزدگی فارم','STATUTORY',NULL,0,1,0,0,'application/pdf,image/jpeg,image/png,image/tiff',10240,14,1,'2026-08-19 05:50:51','2026-08-19 05:50:51'),(15,'FEE_INSTRUMENT','Processing Fee Instrument (Rs. 5,000)','فیس انسٹرومنٹ','FINANCIAL',NULL,0,1,0,0,'application/pdf,image/jpeg,image/png,image/tiff',10240,15,1,'2026-08-19 05:50:51','2026-08-19 05:50:51'),(16,'OTHER','Any Other Supporting Document','دیگر دستاویز','OTHER',NULL,0,0,1,0,'application/pdf,image/jpeg,image/png,image/tiff',10240,99,1,'2026-08-19 05:50:51','2026-08-19 05:50:51');
