INSERT INTO `rate_sources` VALUES (1,'FBR','FBR Notified Valuation Rate','Rate notified by the Federal Board of Revenue.',0,1,0,1,1,'2026-08-19 05:50:51','2026-08-19 05:50:51'),(2,'DC_RATE','DC (District Collector) Rate','Valuation table notified by the District Collector.',0,1,0,2,1,'2026-08-19 05:50:51','2026-08-19 05:50:51'),(3,'NESPAK','NESPAK Rate','Rate assessed by NESPAK.',0,1,0,3,1,'2026-08-19 05:50:51','2026-08-19 05:50:51'),(4,'VALUATOR','Registered Property Valuator','Rate assessed by a registered or approved property valuator.',0,1,0,4,1,'2026-08-19 05:50:51','2026-08-19 05:50:51'),(5,'MARKET_ADJOINING','Prevailing Market Rent (Adjoining Properties)','Prevalent rent of private or other buildings in the vicinity in similar circumstances - the test named in Clause 10(i)(a) and defined in Clause 2(i)(l).',0,0,0,5,1,'2026-08-19 05:50:51','2026-08-19 05:50:51'),(6,'DO_DETERMINED','Rate Determined by District Officer','The operative figure. Requires written reasons under Clause 10(i)(d).',1,0,1,6,1,'2026-08-19 05:50:51','2026-08-19 05:50:51');
