INSERT INTO `unit_conversion_profiles` VALUES (1,'REVENUE','Revenue / Legal Standard (1 Marla = 272.25 sqft)','The Kanal-Marla system used in Pakistani revenue records. 1 Acre = 8 Kanal = 160 Marla = 43,560 sqft.',1,1,'2026-08-19 05:50:51','2026-08-19 05:50:51'),(2,'URBAN','Urban / Housing Society Standard (1 Marla = 225 sqft)','The 25-square-yard Marla used by most urban housing schemes. 1 Kanal = 20 Marla = 4,500 sqft. The Acre is unchanged at 43,560 sqft.',0,1,'2026-08-19 05:50:51','2026-08-19 05:50:51');
